# Решите задачу валидации скобок ()[]{}
def is_valid_brackets(s: str) -> bool:
    mapping = {')': '(', '}': '{', ']': '['}
    stack = []
    for char in s:
        if char in mapping:
            top = stack.pop() if stack else '#'
            if mapping[char] != top:
                return False
        else:
            stack.append(char)
    return len(stack) == 0

class TaggedCache:
    def set(self, key: str, value, tags: list[str], timeout: int = 3600):
        cache.set(key, value, timeout=timeout)

        for tag in tags:
            tag_key = f'tag:{tag}'
            r.sadd(tag_key, key)
            r.expire(tag_key, timeout + 60)

    def invalidate_tag(self, tag: str):
        tag_key = f'tag:{tag}'
        keys = r.smembers(tag_key)

        if keys:
            cache.delete_many(keys)

        r.delete(tag_key)

