# Напишите паттерн Builder для сборки сложного SQL-запроса
class QueryBuilder:
    def __init__(self, table: str):
        self.table = table
        self.fields = ["*"]
        self.conditions = []
        self.limit_val = None

    def select(self, *fields):
        self.fields = list(fields)
        return self

    def where(self, condition):
        self.conditions.append(condition)
        return self

    def limit(self, count):
        self.limit_val = count
        return self

    def build(self) -> str:
        q = f"SELECT {', '.join(self.fields)} FROM {self.table}"
        if self.conditions:
            q += f" WHERE {' AND '.join(self.conditions)}"
        if self.limit_val:
            q += f" LIMIT {self.limit_val}"
        return q

