# Напишите парсер raw HTTP-запроса из байтового потока
def parse_raw_http(raw_bytes: bytes) -> dict:
    headers_part, _, body = raw_bytes.partition(b"\r\n\r\n")
    lines = headers_part.decode("latin1").split("\r\n")
    request_line = lines[0].split(" ")
    method, path, version = request_line[0], request_line[1], request_line[2]
    headers = {}
    for line in lines[1:]:
        if ":" in line:
            k, v = line.split(":", 1)
            headers[k.strip().lower()] = v.strip()
    return {"method": method, "path": path, "headers": headers, "body": body}

