# Рекурсия: O(n) по памяти — стек вызовов растёт с n
def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

# Итерация: O(1) по памяти — используется одна переменная
def factorial_iterative(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

