# Реализуйте приоритетную очередь с кастомными весами
import heapq

class PriorityQueue:
    def __init__(self):
        self._heap = []
        self._index = 0

    def push(self, item, priority):
        # Меньший приоритет вынимается первым (min-heap)
        heapq.heappush(self._heap, (priority, self._index, item))
        self._index += 1

    def pop(self):
        return heapq.heappop(self._heap)[-1]

