# Реализуйте обход в ширину (BFS) с множеством visited
from collections import deque

def bfs(graph: dict, start_node):
    visited = {start_node}
    queue = deque([start_node])
    order = []
    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
    return order

# Реализуйте монотонный стек для поиска следующего большего элемента
def next_greater_elements(nums: list) -> list:
    res = [-1] * len(nums)
    stack = []  # индексы элементов
    for i, num in enumerate(nums):
        while stack and nums[stack[-1]] < num:
            idx = stack.pop()
            res[idx] = num
        stack.append(i)
    return res

