# Автоматический резолвер циклических зависимостей в DI
class DependencyGraph:
    def __init__(self):
        self.adj = {}

    def add_dep(self, service, dep):
        self.adj.setdefault(service, []).append(dep)

    def check_circular(self):
        visited, rec_stack = set(), set()
        def dfs(node):
            visited.add(node); rec_stack.add(node)
            for neighbor in self.adj.get(node, []):
                if neighbor not in visited:
                    if dfs(neighbor): return True
                elif neighbor in rec_stack:
                    return True
            rec_stack.remove(node)
            return False
        return any(dfs(n) for n in self.adj if n not in visited)

