def selection_sort(arr):
    n = len(arr)

    for i in range(n):
        min_idx = i

        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j

        arr[i], arr[min_idx] = arr[min_idx], arr[i]

    return arr

def find_leftmost(arr, target):
    left, right = 0, len(arr) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            result = mid      # запомнили, но продолжаем
            right = mid - 1   # ищем ещё левее
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return result

