import asyncio
import heapq

class AsyncPriorityEventBus:
    def __init__(self):
        self._handlers = {}
        self._seq = 0

    def subscribe(self, event_name: str, priority: int, handler):
        # Меньший номер приоритета выполняется раньше
        self._handlers.setdefault(event_name, [])
        heapq.heappush(self._handlers[event_name], (priority, self._seq, handler))
        self._seq += 1

    async def publish(self, event_name: str, data):
        for _, _, handler in sorted(self._handlers.get(event_name, [])):
            await handler(data)

