# Найдите наименьшего общего предка (LCA) в BST
def lowest_common_ancestor(root: TreeNode, p: TreeNode, q: TreeNode) -> TreeNode:
    curr = root
    while curr:
        if p.val > curr.val and q.val > curr.val:
            curr = curr.right
        elif p.val < curr.val and q.val < curr.val:
            curr = curr.left
        else:
            return curr
    return None

# Напишите рекурсивный обход в глубину (DFS) графа
def dfs_recursive(graph: dict, start_node, visited=None) -> list:
    if visited is None:
        visited = set()
    visited.add(start_node)
    traversal = [start_node]
    for neighbor in graph.get(start_node, []):
        if neighbor not in visited:
            traversal.extend(dfs_recursive(graph, neighbor, visited))
    return traversal

