def count_components(n: int, edges: list) -> int:
    adj = {i: [] for i in range(n)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    visited = set()
    count = 0
    for i in range(n):
        if i not in visited:
            count += 1
            stack = [i]
            visited.add(i)
            while stack:
                curr = stack.pop()
                for neighbor in adj[curr]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        stack.append(neighbor)
    return count

