def cached(key_template: str, timeout: int = 3600):
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = key_template.format(*args, **kwargs)  # например, 'user:42'
            result = cache.get(key)

            if result is None:
                result = func(*args, **kwargs)          # промах — идём в БД
                if result is not None:
                    cache.set(key, result, timeout=timeout)
            return result
        return wrapper
    return decorator

