    deleted = 0
    cursor = 0

    while True:
        cursor, keys = r.scan(
            cursor,
            match=pattern,
            count=100
        )

        if keys:
            r.delete(*keys)
            deleted += len(keys)

        if cursor == 0:
            break

    return deleted


