# Реализуйте фабрику экспортеров отчетов (CSV, JSON, PDF)
class ExporterFactory:
    _exporters = {}

    @classmethod
    def register(cls, fmt, exporter_cls):
        cls._exporters[fmt] = exporter_cls

    @classmethod
    def create(cls, fmt):
        exporter = cls._exporters.get(fmt)
        if not exporter:
            raise ValueError(f"Неизвестный формат экспорта: {fmt}")
        return exporter()

