# Реализуйте паттерн Strategy для расчета доставки
from abc import ABC, abstractmethod

class DeliveryStrategy(ABC):
    @abstractmethod
    def calculate(self, weight: float) -> float: pass

class CourierStrategy(DeliveryStrategy):
    def calculate(self, weight: float) -> float: return 300.0 + weight * 50

class PostStrategy(DeliveryStrategy):
    def calculate(self, weight: float) -> float: return 150.0 + weight * 20

