# Реализуйте паттерн Decorator для компрессии потока данных
import gzip

class DataStream(ABC):
    @abstractmethod
    def write(self, data: bytes) -> bytes: pass

class FileStream(DataStream):
    def write(self, data: bytes) -> bytes: return data

class GzipStreamDecorator(DataStream):
    def __init__(self, stream: DataStream):
        self.stream = stream

    def write(self, data: bytes) -> bytes:
        compressed = gzip.compress(data)
        return self.stream.write(compressed)

