# Устраните дублирование бизнес-логики по правилу DRY
def apply_discount(base_price: float, discount_percent: float, min_price: float = 0.0) -> float:
    discounted = base_price * (1 - discount_percent / 100.0)
    return max(min_price, round(discounted, 2))

